INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G1.CREATI.SELF_AWARENESS.UNIQUE_ME', 'CRE.G1.CREATI.SELF_AWARENESS', 'cre', 1, 'Identify their uniqueness as God''s creation and state their gender (Genesis 1:27)', ARRAY['CRE.G1.CREATI.SELF_AWARENESS.a', 'CRE.G1.CREATI.SELF_AWARENESS.b']::text[], 'Says God made each child special and different (no two children are the same, even twins), that God knows each one by name, and states his or her gender as a boy (male) or girl (female) as God created people male and female (Genesis 1:27). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["who made you","boy or girl","is anyone exactly like you"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G1.CREATI.MY_FAMILY.FAMILY_G1', 'CRE.G1.CREATI.MY_FAMILY', 'cre', 1, 'Name members of their family and items they share at home', ARRAY['CRE.G1.CREATI.MY_FAMILY.a', 'CRE.G1.CREATI.MY_FAMILY.c']::text[], 'Names members of his or her family (father, mother, brothers, sisters, grandparents, or the guardian who cares for the child), and five items a family shares (food, water, chairs, utensils, the house, a radio or television). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G1.RUBRIC.1.1), never as a phone question: b) pray with family members to foster unity.', '["who is this in the family","an item we share","family member or not"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G1.CREATI.CREATION_OF_PLANTS_AND_A.PLANTS_ANIMALS_G1', 'CRE.G1.CREATI.CREATION_OF_PLANTS_AND_A', 'cre', 1, 'Name plants and animals God created (Genesis 1:11, 24)', ARRAY['CRE.G1.CREATI.CREATION_OF_PLANTS_AND_A.a']::text[], 'Names plants (trees, grass, maize, flowers, beans) and animals (cows, goats, birds, fish, dogs) in the environment and says God made them (Genesis 1:11, 24), plants before animals. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G1.RUBRIC.1.1), never as a phone question: b) take part in keeping the home environment clean.', '["plant or animal","who made it","name one"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G1.THE_HO.THE_WORD_OF_GOD.HANDLE_BIBLE', 'CRE.G1.THE_HO.THE_WORD_OF_GOD', 'cre', 1, 'Identify ways of handling the Holy Bible', ARRAY['CRE.G1.THE_HO.THE_WORD_OF_GOD.a']::text[], 'Names ways of handling the Bible with respect: hold it with clean hands, open it gently, do not tear, write or draw in it, do not throw it or sit on it, keep it in a safe clean place, cover it. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["right or wrong way to handle the Bible","name a way to care for it","where to keep it"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G1.THE_HO.THE_WORD_OF_GOD.BIBLE_PARTS', 'CRE.G1.THE_HO.THE_WORD_OF_GOD', 'cre', 1, 'Mention the two divisions of the Bible and name the first two books of the New Testament', ARRAY['CRE.G1.THE_HO.THE_WORD_OF_GOD.b', 'CRE.G1.THE_HO.THE_WORD_OF_GOD.c']::text[], 'Says the Bible has two divisions, the Old Testament and the New Testament, and names Matthew and Mark as the first two books of the New Testament. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["two parts of the Bible","first book of the New Testament","second book"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H.JOSEPH', 'CRE.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H', 'cre', 1, 'Narrate the story of Joseph and his brothers (Genesis 37)', ARRAY['CRE.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H.a']::text[], 'Narrates Genesis 37: Jacob loved Joseph and gave him a richly coloured coat; his brothers were jealous; Joseph dreamt their sheaves bowed to his; the brothers hated him more and sold him to traders going to Egypt, then told their father a wild animal had killed him. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what Jacob gave Joseph","why the brothers were angry","what they did"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H.SIBLINGS', 'CRE.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H', 'cre', 1, 'Discuss how to treat siblings and name values for peaceful living', ARRAY['CRE.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H.b', 'CRE.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H.c']::text[], 'Says how to treat brothers and sisters well (share, help, play together, say sorry, not fight or tease, not be jealous) and names values for peaceful co-existence: love, sharing, forgiveness, respect, kindness. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["kind or unkind to a sibling","a value for living in peace","what to do here"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G1.THE_HO.BIBLE_STORY_THE_CHARIOT_.ELIJAH_CHARIOT', 'CRE.G1.THE_HO.BIBLE_STORY_THE_CHARIOT_', 'cre', 1, 'Retell the story of Elijah and the chariot of fire and list ways of a good relationship with God (2 Kings 2:1, 11-12)', ARRAY['CRE.G1.THE_HO.BIBLE_STORY_THE_CHARIOT_.a', 'CRE.G1.THE_HO.BIBLE_STORY_THE_CHARIOT_.b']::text[], 'Retells 2 Kings 2:1, 11-12: Elijah and Elisha were walking together; a chariot of fire with horses of fire came between them; Elijah went up to heaven in a whirlwind; Elisha saw it and cried out. Lists ways to have a good relationship with God: pray, read the Bible, obey God and parents, go to church or Sunday school, be kind. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["how Elijah went to heaven","who was with him","a way to please God"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G1.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.BIRTH_JESUS', 'CRE.G1.THE_EA.THE_BIRTH_OF_JESUS_CHRIS', 'cre', 1, 'Retell the birth of Jesus Christ (Luke 2:4-13)', ARRAY['CRE.G1.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.a']::text[], 'Retells Luke 2:4-13: Joseph and Mary travelled from Nazareth to Bethlehem; there was no room in the inn; Jesus was born and laid in a manger; an angel told shepherds the good news and many angels praised God, "Glory to God in the highest". Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G1.RUBRIC.2.1), never as a phone question: b) dramatise the birth of Jesus Christ; c) express the joy of the angels through song and dance.', '["where Jesus was born","where he was laid","who told the shepherds"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G1.THE_EA.JESUS_CHRIST_IN_THE_TEMP.TEMPLE_BOY', 'CRE.G1.THE_EA.JESUS_CHRIST_IN_THE_TEMP', 'cre', 1, 'Retell the story of Jesus in the temple at twelve (Luke 2:42-49)', ARRAY['CRE.G1.THE_EA.JESUS_CHRIST_IN_THE_TEMP.a']::text[], 'Retells Luke 2:42-49: when Jesus was twelve, his family went to Jerusalem for the Passover; on the way home his parents could not find him; after three days they found him in the temple sitting among the teachers, listening and asking questions; he said he had to be in his Father''s house; then he went home and obeyed them (Luke 2:51). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G1.RUBRIC.2.1), never as a phone question: b) obey their parents as portrayed by Jesus Christ; c) take part in Sunday or Sabbath school activities.', '["how old Jesus was","where his parents found him","what he was doing"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G1.THE_EA.BAPTISM_OF_JESUS_CHRIST.BAPTISM_JESUS', 'CRE.G1.THE_EA.BAPTISM_OF_JESUS_CHRIST', 'cre', 1, 'Name the place where Jesus was baptised and the person who baptised him (Matthew 3:13-15)', ARRAY['CRE.G1.THE_EA.BAPTISM_OF_JESUS_CHRIST.a', 'CRE.G1.THE_EA.BAPTISM_OF_JESUS_CHRIST.b']::text[], 'Names the River Jordan as the place and John the Baptist as the person who baptised Jesus (Matthew 3:13-15), and says John felt Jesus should baptise him, showing humility, but Jesus asked to be baptised. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G1.RUBRIC.2.1), never as a phone question: c) practise humility in their interaction with others.', '["where","who","what John said"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G1.THE_EA.WEDDING_AT_CANA_OF_GALIL.CANA', 'CRE.G1.THE_EA.WEDDING_AT_CANA_OF_GALIL', 'cre', 1, 'Retell how Jesus changed water into wine (John 2:1-10)', ARRAY['CRE.G1.THE_EA.WEDDING_AT_CANA_OF_GALIL.a']::text[], 'Retells John 2:1-10: at a wedding in Cana the wine ran out; Mary told Jesus and told the servants "Do whatever he tells you"; Jesus told them to fill six stone jars with water and take some to the master of the banquet; it had become wine, the best wine. It was Jesus'' first miracle. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G1.RUBRIC.2.1), never as a phone question: b) obey instructions as portrayed in the wedding at Cana.', '["what ran out","what Jesus told the servants","what happened"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G1.THE_EA.HEALING_SIMON_S_MOTHER_I.SIMON_MIL', 'CRE.G1.THE_EA.HEALING_SIMON_S_MOTHER_I', 'cre', 1, 'Retell the healing of Simon''s mother-in-law (Luke 4:38-39)', ARRAY['CRE.G1.THE_EA.HEALING_SIMON_S_MOTHER_I.a']::text[], 'Retells Luke 4:38-39: Simon''s mother-in-law had a high fever; they asked Jesus to help her; he bent over her and rebuked the fever, and it left her; she got up at once and began to serve them, showing her thanks. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G1.RUBRIC.2.1), never as a phone question: b) show gratitude to others as portrayed by Simon’s mother- in- law.', '["what was wrong with her","what Jesus did","what she did after"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G1.CHRIST.SHARING.SHARE_HOME', 'CRE.G1.CHRIST.SHARING', 'cre', 1, 'Identify items they share at home as a family', ARRAY['CRE.G1.CHRIST.SHARING.a']::text[], 'Names items a family shares at home (food, water, chairs, the table, utensils, the radio or television, the house) and says sharing shows love; personal items (toothbrush, towel, comb) are not shared. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G1.RUBRIC.2.1), never as a phone question: b) practise the value of sharing at home and school.', '["shared or personal","name an item we share","why share"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G1.CHRIST.SHARING.BOY_LOAVES', 'CRE.G1.CHRIST.SHARING', 'cre', 1, 'Retell the story of the little boy with two fish and five loaves (John 6:1-14)', ARRAY['CRE.G1.CHRIST.SHARING.c']::text[], 'Retells John 6:1-14: a large crowd was hungry; a little boy had five loaves and two fish; he gave them to Jesus; Jesus gave thanks and shared them; everyone ate; twelve baskets of leftovers were gathered so nothing was wasted. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what the boy had","what Jesus did","what was left"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G1.CHRIST.OBEDIENCE.OBEY_PARENTS', 'CRE.G1.CHRIST.OBEDIENCE', 'cre', 1, 'List the importance of obeying parents (Ephesians 6:1-3)', ARRAY['CRE.G1.CHRIST.OBEDIENCE.a']::text[], 'Lists why children obey parents: God commands it (Ephesians 6:1: children, obey your parents in the Lord, for this is right), it keeps them safe, things go well and they enjoy long life (6:3), it pleases parents; and knows children never obey anyone asking for something unsafe or secret. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G1.RUBRIC.2.1), never as a phone question: b) practise obedience at home as guided by the scriptures.', '["why obey parents","obedient or not","what Ephesians 6:1 says"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G1.CHRIST.HONESTY.TRUTH_G1', 'CRE.G1.CHRIST.HONESTY', 'cre', 1, 'State reasons for telling the truth (Ephesians 4:25)', ARRAY['CRE.G1.CHRIST.HONESTY.a']::text[], 'States reasons for telling the truth: God wants us to speak truthfully (Ephesians 4:25), people trust us, lies cause trouble, and we are not afraid; and recognises honest acts (not taking others'' things, owning up). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G1.RUBRIC.2.1), never as a phone question: b) demonstrate honesty by not stealing other people’s items; c) practise punctuality at school and home.', '["why tell the truth","true or a lie","honest or not"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G1.CHRIST.THANKFULNESS.THANK_PARENTS', 'CRE.G1.CHRIST.THANKFULNESS', 'cre', 1, 'Mention ways of expressing gratitude to parents or guardians', ARRAY['CRE.G1.CHRIST.THANKFULNESS.a']::text[], 'Mentions three ways of thanking parents or guardians: saying thank you, helping with chores, obeying them, praying for them, making a card or drawing, giving a hug. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G1.RUBRIC.2.1), never as a phone question: b) practise thankfulness at home as guided by the Bible.', '["a way to thank parents","thankful or not","when to say thank you"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G1.THE_CH.A_HOUSE_OF_GOD.CHURCH_G1', 'CRE.G1.THE_CH.A_HOUSE_OF_GOD', 'cre', 1, 'Recognise the church as a place of worship and ways of respecting it', ARRAY['CRE.G1.THE_CH.A_HOUSE_OF_GOD.a']::text[], 'Says the church is a place where Christians worship God (pray, sing, read the Bible, listen to God''s word) and names ways of respecting it: walk quietly, listen, keep it clean, do not run or shout, take part in worship. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G1.RUBRIC.3.1), never as a phone question: b) demonstrate responsibility by serving God in Church.', '["what we do in church","respectful or not","why we respect church"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G1.THE_CH.A_HOUSE_OF_PRAYER.PRAYER_TIMES', 'CRE.G1.THE_CH.A_HOUSE_OF_PRAYER', 'cre', 1, 'Say simple prayers at different times of the day (Matthew 21:13)', ARRAY['CRE.G1.THE_CH.A_HOUSE_OF_PRAYER.b']::text[], 'Says Christians can pray at different times of the day (morning, before meals, before school, at bedtime, when afraid or sick), that God''s house is a house of prayer (Matthew 21:13), and that a simple prayer talks to God: thank you, please, sorry. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CRE.G1.RUBRIC.3.1), never as a phone question: a) recite simple thanksgiving prayers.', '["when can we pray","what to say in a prayer","who we talk to"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
