INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G1.THE_CH.A_HOUSE_OF_GOD.CHURCH_G1', 'CRES.G1.THE_HO.THE_WORD_OF_GOD.HANDLE_BIBLE', 'skill', 'essential', 'Respect for God''s word, read in church. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G1.THE_CH.A_HOUSE_OF_PRAYER.PRAYER_TIMES', 'CRE.PP2.READINESS.SHORT_PRAYER', 'skill', 'essential', 'Saying a short prayer. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G1.THE_CH.A_HOUSE_OF_PRAYER.PRAYER_TIMES', 'CRES.G1.THE_CH.A_HOUSE_OF_GOD.CHURCH_G1', 'skill', 'essential', 'The church as a house of God. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CREATI.SELF_AWARENESS.UNIQUE_ME.M_C1_UNI_SAME', 'CRES.G1.CREATI.SELF_AWARENESS.UNIQUE_ME', 'Thinks twins or siblings are exactly the same person.', '{"question":"Are twins exactly the same?","wrong_answer":"Yes, the same","correct_answer":"No, each is special and different"}'::jsonb, 'Twins look alike.', 'Offer "Yes, the same" beside "No, each is special and different" and ask the child to choose.', 'Compare thumbprints of two children, or two leaves of one tree.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CREATI.SELF_AWARENESS.UNIQUE_ME.M_C1_UNI_GENDER_CLOTHES', 'CRES.G1.CREATI.SELF_AWARENESS.UNIQUE_ME', 'Thinks a girl becomes a boy if she wears trousers or has short hair.', '{"question":"A girl has short hair. Is she still a girl?","wrong_answer":"No, she is a boy now","correct_answer":"Yes, she is a girl"}'::jsonb, 'Young children judge gender by clothes and hair.', 'Offer "No, she is a boy now" beside "Yes, she is a girl" and ask the child to choose.', 'Say: God made you a boy or a girl; clothes and hair do not change it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CREATI.SELF_AWARENESS.UNIQUE_ME.M_C1_UNI_GOD_FORGETS', 'CRES.G1.CREATI.SELF_AWARENESS.UNIQUE_ME', 'Thinks God does not know small children''s names.', '{"question":"Does God know your name?","wrong_answer":"No, I am too small","correct_answer":"Yes, God knows me by name"}'::jsonb, 'Big people seem more important.', 'Offer "No, I am too small" beside "Yes, God knows me by name" and ask the child to choose.', 'Say Isaiah 43:1 simply: God says, "I have called you by name."', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CREATI.SELF_AWARENESS.UNIQUE_ME.M_C1_UNI_MADE_BY', 'CRES.G1.CREATI.SELF_AWARENESS.UNIQUE_ME', 'Thinks children were made by the hospital or bought.', '{"question":"Who made you?","wrong_answer":"The hospital","correct_answer":"God"}'::jsonb, 'Babies come home from hospital.', 'Offer "The hospital" beside "God" and ask the child to choose.', 'Sing a song about God making me. Read Genesis 1:27 with pictures.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CREATI.MY_FAMILY.FAMILY_G1.M_C1_FAM_PETS', 'CRES.G1.CREATI.MY_FAMILY.FAMILY_G1', 'Lists the dog or cat as a family member instead of people.', '{"question":"Name a member of your family.","wrong_answer":"My dog","correct_answer":"My mother (father, sister)"}'::jsonb, 'Pets live at home and are loved.', 'Offer "My dog" beside "My mother (father, sister)" and ask the child to choose.', 'Sort pictures: people in the family and animals at home.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CREATI.MY_FAMILY.FAMILY_G1.M_C1_FAM_TOOTHBRUSH', 'CRES.G1.CREATI.MY_FAMILY.FAMILY_G1', 'Lists a toothbrush as an item the family shares.', '{"question":"Does a family share one toothbrush?","wrong_answer":"Yes","correct_answer":"No, each has his own"}'::jsonb, 'Sharing is always praised.', 'Offer "Yes" beside "No, each has his own" and ask the child to choose.', 'Show personal items and shared items in two baskets.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CREATI.MY_FAMILY.FAMILY_G1.M_C1_FAM_TWO_ONLY', 'CRES.G1.CREATI.MY_FAMILY.FAMILY_G1', 'Thinks a family is only a mother and a father.', '{"question":"Are brothers and sisters part of the family?","wrong_answer":"No","correct_answer":"Yes"}'::jsonb, 'The child pictures parents as the family.', 'Offer "No" beside "Yes" and ask the child to choose.', 'Draw a family with children and grandparents.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CREATI.MY_FAMILY.FAMILY_G1.M_C1_FAM_SHARE_NONE', 'CRES.G1.CREATI.MY_FAMILY.FAMILY_G1', 'Thinks his things at home should never be shared.', '{"question":"Should a family share food at home?","wrong_answer":"No, my food is mine","correct_answer":"Yes, families share food"}'::jsonb, 'Young children guard their things.', 'Offer "No, my food is mine" beside "Yes, families share food" and ask the child to choose.', 'Role-play a family meal where food is shared.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CREATI.CREATION_OF_PLANTS_AND_A.PLANTS_ANIMALS_G1.M_C1_PA_TREE_ANIMAL', 'CRES.G1.CREATI.CREATION_OF_PLANTS_AND_A.PLANTS_ANIMALS_G1', 'Calls a tree an animal because it is alive.', '{"question":"Is a tree a plant or an animal?","wrong_answer":"An animal","correct_answer":"A plant"}'::jsonb, 'Living things are mixed.', 'Offer "An animal" beside "A plant" and ask the child to choose.', 'Sort pictures: plants stay in one place and grow from the ground; animals move and eat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CREATI.CREATION_OF_PLANTS_AND_A.PLANTS_ANIMALS_G1.M_C1_PA_FISH_NOT', 'CRES.G1.CREATI.CREATION_OF_PLANTS_AND_A.PLANTS_ANIMALS_G1', 'Thinks fish and birds are not animals.', '{"question":"Is a fish an animal?","wrong_answer":"No","correct_answer":"Yes"}'::jsonb, 'Animal means four legs to young children.', 'Offer "No" beside "Yes" and ask the child to choose.', 'Show animals that swim, fly and walk.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CREATI.CREATION_OF_PLANTS_AND_A.PLANTS_ANIMALS_G1.M_C1_PA_FARMER_MADE', 'CRES.G1.CREATI.CREATION_OF_PLANTS_AND_A.PLANTS_ANIMALS_G1', 'Thinks the farmer made the plants and animals.', '{"question":"Who created plants and animals?","wrong_answer":"The farmer","correct_answer":"God"}'::jsonb, 'Farmers grow crops and keep animals.', 'Offer "The farmer" beside "God" and ask the child to choose.', 'Read Genesis 1:11, 24. Farmers care for what God made.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CREATI.CREATION_OF_PLANTS_AND_A.PLANTS_ANIMALS_G1.M_C1_PA_FLOWER_NOT', 'CRES.G1.CREATI.CREATION_OF_PLANTS_AND_A.PLANTS_ANIMALS_G1', 'Thinks flowers or grass are not plants.', '{"question":"Is grass a plant?","wrong_answer":"No","correct_answer":"Yes"}'::jsonb, 'Plant means crops in the garden.', 'Offer "No" beside "Yes" and ask the child to choose.', 'Walk outside and touch grass, flowers, trees: all plants.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_HO.THE_WORD_OF_GOD.HANDLE_BIBLE.M_C1_HB_DRAW', 'CRES.G1.THE_HO.THE_WORD_OF_GOD.HANDLE_BIBLE', 'Thinks it is fine to draw pictures in the Bible.', '{"question":"Can you draw in the Bible?","wrong_answer":"Yes","correct_answer":"No, keep it clean"}'::jsonb, 'Children draw in many books.', 'Offer "Yes" beside "No, keep it clean" and ask the child to choose.', 'Show a clean Bible and a scribbled book. Agree how we treat God''s book.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_HO.THE_WORD_OF_GOD.HANDLE_BIBLE.M_C1_HB_FLOOR', 'CRES.G1.THE_HO.THE_WORD_OF_GOD.HANDLE_BIBLE', 'Thinks the Bible can be put on the floor or used as a seat.', '{"question":"Where should you keep the Bible?","wrong_answer":"On the floor","correct_answer":"In a clean safe place"}'::jsonb, 'Things are put down anywhere.', 'Offer "On the floor" beside "In a clean safe place" and ask the child to choose.', 'Choose a special shelf in class for the Bible.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_HO.THE_WORD_OF_GOD.HANDLE_BIBLE.M_C1_HB_DIRTY_HANDS', 'CRES.G1.THE_HO.THE_WORD_OF_GOD.HANDLE_BIBLE', 'Thinks hands need not be clean to hold the Bible.', '{"question":"What should your hands be like when you hold the Bible?","wrong_answer":"Any way","correct_answer":"Clean"}'::jsonb, 'Washing is for meals.', 'Offer "Any way" beside "Clean" and ask the child to choose.', 'Wash hands before Bible time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_HO.THE_WORD_OF_GOD.HANDLE_BIBLE.M_C1_HB_THROW', 'CRES.G1.THE_HO.THE_WORD_OF_GOD.HANDLE_BIBLE', 'Thinks tossing the Bible to a friend is fine.', '{"question":"Can you throw the Bible to your friend?","wrong_answer":"Yes","correct_answer":"No, hand it gently"}'::jsonb, 'Books are passed by throwing in play.', 'Offer "Yes" beside "No, hand it gently" and ask the child to choose.', 'Practise passing the Bible with two hands.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_HO.THE_WORD_OF_GOD.BIBLE_PARTS.M_C1_BP_THREE', 'CRES.G1.THE_HO.THE_WORD_OF_GOD.BIBLE_PARTS', 'Thinks the Bible has many parts, one for each story.', '{"question":"How many divisions does the Bible have?","wrong_answer":"Many","correct_answer":"Two"}'::jsonb, 'The Bible has many stories.', 'Offer "Many" beside "Two" and ask the child to choose.', 'Show a Bible with a ribbon between the two parts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_HO.THE_WORD_OF_GOD.BIBLE_PARTS.M_C1_BP_GENESIS', 'CRES.G1.THE_HO.THE_WORD_OF_GOD.BIBLE_PARTS', 'Names Genesis as the first New Testament book.', '{"question":"What is the first book of the New Testament?","wrong_answer":"Genesis","correct_answer":"Matthew"}'::jsonb, 'Genesis is the first page.', 'Offer "Genesis" beside "Matthew" and ask the child to choose.', 'Open at the ribbon: the New Testament starts with Matthew.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_HO.THE_WORD_OF_GOD.BIBLE_PARTS.M_C1_BP_NAMES', 'CRES.G1.THE_HO.THE_WORD_OF_GOD.BIBLE_PARTS', 'Names the testaments as "the old book and the new book" bought at different times.', '{"question":"What does \"New Testament\" mean?","wrong_answer":"A newer copy of the Bible","correct_answer":"The second part of the Bible"}'::jsonb, 'New means just bought.', 'Offer "A newer copy of the Bible" beside "The second part of the Bible" and ask the child to choose.', 'Show both parts in one Bible.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_HO.THE_WORD_OF_GOD.BIBLE_PARTS.M_C1_BP_ORDER', 'CRES.G1.THE_HO.THE_WORD_OF_GOD.BIBLE_PARTS', 'Puts Mark before Matthew.', '{"question":"Which comes first: Matthew or Mark?","wrong_answer":"Mark","correct_answer":"Matthew"}'::jsonb, 'Both start with M.', 'Offer "Mark" beside "Matthew" and ask the child to choose.', 'Clap "Mat-thew, Mark" in order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H.JOSEPH.M_C1_JOS_GIFT_BROTHERS', 'CRES.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H.JOSEPH', 'Thinks all the brothers got coats.', '{"question":"Who got the coat of many colours?","wrong_answer":"All the brothers","correct_answer":"Only Joseph"}'::jsonb, 'Parents give to all children.', 'Offer "All the brothers" beside "Only Joseph" and ask the child to choose.', 'Show one coloured coat and plain clothes for the brothers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H.JOSEPH.M_C1_JOS_HAPPY', 'CRES.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H.JOSEPH', 'Thinks the brothers were happy for Joseph.', '{"question":"How did the brothers feel about Joseph''s coat?","wrong_answer":"Happy","correct_answer":"Jealous"}'::jsonb, 'Children expect families to be happy.', 'Offer "Happy" beside "Jealous" and ask the child to choose.', 'Make a jealous face and name it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H.JOSEPH.M_C1_JOS_KILLED', 'CRES.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H.JOSEPH', 'Thinks a wild animal really killed Joseph.', '{"question":"Did a wild animal kill Joseph?","wrong_answer":"Yes","correct_answer":"No, his brothers sold him and lied"}'::jsonb, 'The child believes the brothers'' words.', 'Offer "Yes" beside "No, his brothers sold him and lied" and ask the child to choose.', 'Tell the story again slowly: sold to traders, then the lie.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H.JOSEPH.M_C1_JOS_DREAM', 'CRES.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H.JOSEPH', 'Thinks Joseph dreamt about the coat.', '{"question":"What did Joseph dream about?","wrong_answer":"His coat","correct_answer":"His brothers'' sheaves bowing to his"}'::jsonb, 'The coat is the most vivid part.', 'Offer "His coat" beside "His brothers'' sheaves bowing to his" and ask the child to choose.', 'Draw bundles of grain bowing to one bundle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H.SIBLINGS.M_C1_SIB_FIGHT', 'CRES.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H.SIBLINGS', 'Thinks hitting a sibling who takes your toy is right.', '{"question":"Your brother takes your toy. What should you do?","wrong_answer":"Hit him","correct_answer":"Ask him to give it back or tell a parent"}'::jsonb, 'Hitting back seems fair.', 'Offer "Hit him" beside "Ask him to give it back or tell a parent" and ask the child to choose.', 'Role-play asking kindly and telling a parent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H.SIBLINGS.M_C1_SIB_JEALOUS', 'CRES.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H.SIBLINGS', 'Thinks it is fine to be angry when a sibling gets something.', '{"question":"Your sister gets new shoes. What should you do?","wrong_answer":"Be angry","correct_answer":"Be happy for her"}'::jsonb, 'Jealousy is a natural first feeling.', 'Offer "Be angry" beside "Be happy for her" and ask the child to choose.', 'Link with Joseph''s brothers. Practise saying "I am happy for you".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H.SIBLINGS.M_C1_SIB_VALUE_MONEY', 'CRES.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H.SIBLINGS', 'Names money or toys as values for living in peace.', '{"question":"Which helps a family live in peace: love or a new toy?","wrong_answer":"A new toy","correct_answer":"Love"}'::jsonb, 'Value is a new word.', 'Offer "A new toy" beside "Love" and ask the child to choose.', 'Show values cards: love, sharing, forgiveness.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H.SIBLINGS.M_C1_SIB_SORRY', 'CRES.G1.THE_HO.BIBLE_STORY_JOSEPH_AND_H.SIBLINGS', 'Thinks saying sorry is only for the younger child.', '{"question":"Who should say sorry after a quarrel?","wrong_answer":"Only the younger one","correct_answer":"The one who did wrong, even if older"}'::jsonb, 'Older children are rarely made to apologise.', 'Offer "Only the younger one" beside "The one who did wrong, even if older" and ask the child to choose.', 'Role-play an older sibling saying sorry.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_HO.BIBLE_STORY_THE_CHARIOT_.ELIJAH_CHARIOT.M_C1_ELI_DIED', 'CRES.G1.THE_HO.BIBLE_STORY_THE_CHARIOT_.ELIJAH_CHARIOT', 'Thinks Elijah died and was buried.', '{"question":"How did Elijah leave the earth?","wrong_answer":"He died and was buried","correct_answer":"He went up to heaven in a whirlwind"}'::jsonb, 'Everyone who leaves the story dies.', 'Offer "He died and was buried" beside "He went up to heaven in a whirlwind" and ask the child to choose.', 'Read 2 Kings 2:11 with a picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_HO.BIBLE_STORY_THE_CHARIOT_.ELIJAH_CHARIOT.M_C1_ELI_CAR', 'CRES.G1.THE_HO.BIBLE_STORY_THE_CHARIOT_.ELIJAH_CHARIOT', 'Thinks a chariot is a car or a lorry.', '{"question":"What came between Elijah and Elisha?","wrong_answer":"A car","correct_answer":"A chariot of fire with horses of fire"}'::jsonb, 'Chariot is a new word.', 'Offer "A car" beside "A chariot of fire with horses of fire" and ask the child to choose.', 'Show a picture of a chariot pulled by horses.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_HO.BIBLE_STORY_THE_CHARIOT_.ELIJAH_CHARIOT.M_C1_ELI_ALONE', 'CRES.G1.THE_HO.BIBLE_STORY_THE_CHARIOT_.ELIJAH_CHARIOT', 'Thinks Elijah was alone.', '{"question":"Who was with Elijah?","wrong_answer":"Nobody","correct_answer":"Elisha"}'::jsonb, 'Names are hard.', 'Offer "Nobody" beside "Elisha" and ask the child to choose.', 'Use two name cards.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_HO.BIBLE_STORY_THE_CHARIOT_.ELIJAH_CHARIOT.M_C1_ELI_GOOD_REL', 'CRES.G1.THE_HO.BIBLE_STORY_THE_CHARIOT_.ELIJAH_CHARIOT', 'Thinks being friends with God means getting things from God.', '{"question":"Name a way to have a good relationship with God.","wrong_answer":"Ask God for toys","correct_answer":"Pray (read the Bible, obey)"}'::jsonb, 'Prayer is heard mostly as asking.', 'Offer "Ask God for toys" beside "Pray (read the Bible, obey)" and ask the child to choose.', 'List: pray, read the Bible, obey, go to Sunday school.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.BIRTH_JESUS.M_C1_BJ_HOSPITAL', 'CRES.G1.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.BIRTH_JESUS', 'Thinks Jesus was born in a hospital or a house.', '{"question":"Where was baby Jesus laid after he was born?","wrong_answer":"In a hospital bed","correct_answer":"In a manger"}'::jsonb, 'Babies today are born in hospitals.', 'Offer "In a hospital bed" beside "In a manger" and ask the child to choose.', 'Show a manger: a feeding box for animals.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.BIRTH_JESUS.M_C1_BJ_NAZARETH', 'CRES.G1.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.BIRTH_JESUS', 'Thinks Jesus was born in Nazareth or Nairobi.', '{"question":"In which town was Jesus born?","wrong_answer":"Nazareth","correct_answer":"Bethlehem"}'::jsonb, 'Nazareth is also in the story.', 'Offer "Nazareth" beside "Bethlehem" and ask the child to choose.', 'Draw the journey from Nazareth to Bethlehem.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.BIRTH_JESUS.M_C1_BJ_WISE_ANGEL', 'CRES.G1.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.BIRTH_JESUS', 'Thinks the wise men told the shepherds.', '{"question":"Who told the shepherds about baby Jesus?","wrong_answer":"The wise men","correct_answer":"An angel"}'::jsonb, 'All Christmas visitors are mixed.', 'Offer "The wise men" beside "An angel" and ask the child to choose.', 'Show an angel appearing to shepherds at night.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.BIRTH_JESUS.M_C1_BJ_INN_ROOM', 'CRES.G1.THE_EA.THE_BIRTH_OF_JESUS_CHRIS.BIRTH_JESUS', 'Thinks Mary and Joseph stayed in the inn.', '{"question":"Was there room for Mary and Joseph in the inn?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Travellers stay in inns.', 'Offer "Yes" beside "No" and ask the child to choose.', 'Read Luke 2:7 and act knocking at a full inn.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_EA.JESUS_CHRIST_IN_THE_TEMP.TEMPLE_BOY.M_C1_TB_BABY', 'CRES.G1.THE_EA.JESUS_CHRIST_IN_THE_TEMP.TEMPLE_BOY', 'Thinks Jesus was a baby in this story.', '{"question":"How old was Jesus when he stayed in the temple?","wrong_answer":"A baby","correct_answer":"Twelve years"}'::jsonb, 'Jesus as a child is pictured as a baby.', 'Offer "A baby" beside "Twelve years" and ask the child to choose.', 'Show a picture of a boy of twelve.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_EA.JESUS_CHRIST_IN_THE_TEMP.TEMPLE_BOY.M_C1_TB_LOST_PLAY', 'CRES.G1.THE_EA.JESUS_CHRIST_IN_THE_TEMP.TEMPLE_BOY', 'Thinks Jesus was lost playing in the market.', '{"question":"Where did his parents find Jesus?","wrong_answer":"In the market playing","correct_answer":"In the temple with the teachers"}'::jsonb, 'Lost children are found playing.', 'Offer "In the market playing" beside "In the temple with the teachers" and ask the child to choose.', 'Read Luke 2:46.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_EA.JESUS_CHRIST_IN_THE_TEMP.TEMPLE_BOY.M_C1_TB_TEACHING_ADULTS', 'CRES.G1.THE_EA.JESUS_CHRIST_IN_THE_TEMP.TEMPLE_BOY', 'Thinks Jesus was shouting at or teaching the teachers rudely.', '{"question":"What was Jesus doing in the temple?","wrong_answer":"Shouting at the teachers","correct_answer":"Listening and asking questions"}'::jsonb, 'Children picture a clever boy showing off.', 'Offer "Shouting at the teachers" beside "Listening and asking questions" and ask the child to choose.', 'Act it out: sit, listen, ask.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_EA.JESUS_CHRIST_IN_THE_TEMP.TEMPLE_BOY.M_C1_TB_DISOBEYED', 'CRES.G1.THE_EA.JESUS_CHRIST_IN_THE_TEMP.TEMPLE_BOY', 'Thinks Jesus refused to go home with his parents.', '{"question":"What did Jesus do after his parents found him?","wrong_answer":"Refused to go home","correct_answer":"Went home and obeyed them"}'::jsonb, 'The story seems to show him staying.', 'Offer "Refused to go home" beside "Went home and obeyed them" and ask the child to choose.', 'Read Luke 2:51.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_EA.BAPTISM_OF_JESUS_CHRIST.BAPTISM_JESUS.M_C1_BAP_PETER', 'CRES.G1.THE_EA.BAPTISM_OF_JESUS_CHRIST.BAPTISM_JESUS', 'Says Peter or a pastor baptised Jesus.', '{"question":"Who baptised Jesus?","wrong_answer":"Peter","correct_answer":"John the Baptist"}'::jsonb, 'Peter is a well-known name.', 'Offer "Peter" beside "John the Baptist" and ask the child to choose.', 'Show a name card "John the Baptist" by a river picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_EA.BAPTISM_OF_JESUS_CHRIST.BAPTISM_JESUS.M_C1_BAP_CHURCH', 'CRES.G1.THE_EA.BAPTISM_OF_JESUS_CHRIST.BAPTISM_JESUS', 'Thinks Jesus was baptised in a church.', '{"question":"Where was Jesus baptised?","wrong_answer":"In a church","correct_answer":"In the River Jordan"}'::jsonb, 'Baptisms the child sees are in church.', 'Offer "In a church" beside "In the River Jordan" and ask the child to choose.', 'Show a river picture. Read Matthew 3:13.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_EA.BAPTISM_OF_JESUS_CHRIST.BAPTISM_JESUS.M_C1_BAP_LAKE', 'CRES.G1.THE_EA.BAPTISM_OF_JESUS_CHRIST.BAPTISM_JESUS', 'Names the Sea of Galilee or Lake Victoria.', '{"question":"Which river?","wrong_answer":"Lake Victoria","correct_answer":"The River Jordan"}'::jsonb, 'Known big water comes to mind.', 'Offer "Lake Victoria" beside "The River Jordan" and ask the child to choose.', 'Say "Jordan" with a river action.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_EA.BAPTISM_OF_JESUS_CHRIST.BAPTISM_JESUS.M_C1_BAP_JOHN_PROUD', 'CRES.G1.THE_EA.BAPTISM_OF_JESUS_CHRIST.BAPTISM_JESUS', 'Thinks John was proud to baptise Jesus.', '{"question":"What did John say when Jesus came?","wrong_answer":"I am greater than you","correct_answer":"I need to be baptised by you"}'::jsonb, 'The baptiser seems the important one.', 'Offer "I am greater than you" beside "I need to be baptised by you" and ask the child to choose.', 'Read Matthew 3:14: John was humble.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_EA.WEDDING_AT_CANA_OF_GALIL.CANA.M_C1_CANA_FOOD', 'CRES.G1.THE_EA.WEDDING_AT_CANA_OF_GALIL.CANA', 'Thinks the food ran out.', '{"question":"What ran out at the wedding?","wrong_answer":"Food","correct_answer":"Wine"}'::jsonb, 'Feasts run out of food.', 'Offer "Food" beside "Wine" and ask the child to choose.', 'Read John 2:3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_EA.WEDDING_AT_CANA_OF_GALIL.CANA.M_C1_CANA_SHOP', 'CRES.G1.THE_EA.WEDDING_AT_CANA_OF_GALIL.CANA', 'Thinks Jesus bought more wine.', '{"question":"How did Jesus help?","wrong_answer":"He bought wine","correct_answer":"He changed water into wine"}'::jsonb, 'Running out means buying more.', 'Offer "He bought wine" beside "He changed water into wine" and ask the child to choose.', 'Act it out with jars of water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_EA.WEDDING_AT_CANA_OF_GALIL.CANA.M_C1_CANA_MILK', 'CRES.G1.THE_EA.WEDDING_AT_CANA_OF_GALIL.CANA', 'Thinks the water became milk or juice.', '{"question":"What did the water become?","wrong_answer":"Milk","correct_answer":"Wine"}'::jsonb, 'Wine is not a child''s drink.', 'Offer "Milk" beside "Wine" and ask the child to choose.', 'Read John 2:9.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_EA.WEDDING_AT_CANA_OF_GALIL.CANA.M_C1_CANA_SERVANTS_NO', 'CRES.G1.THE_EA.WEDDING_AT_CANA_OF_GALIL.CANA', 'Thinks the servants refused to obey.', '{"question":"What did the servants do when Jesus spoke?","wrong_answer":"Refused","correct_answer":"Filled the jars as he said"}'::jsonb, 'Carrying water is hard work.', 'Offer "Refused" beside "Filled the jars as he said" and ask the child to choose.', 'Read John 2:7-8 and act it out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_EA.HEALING_SIMON_S_MOTHER_I.SIMON_MIL.M_C1_SIM_LEG', 'CRES.G1.THE_EA.HEALING_SIMON_S_MOTHER_I.SIMON_MIL', 'Thinks she had a broken leg.', '{"question":"What was wrong with Simon''s mother-in-law?","wrong_answer":"A broken leg","correct_answer":"A high fever"}'::jsonb, 'Illness is pictured as injury.', 'Offer "A broken leg" beside "A high fever" and ask the child to choose.', 'Touch a forehead: hot means fever.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_EA.HEALING_SIMON_S_MOTHER_I.SIMON_MIL.M_C1_SIM_MEDICINE', 'CRES.G1.THE_EA.HEALING_SIMON_S_MOTHER_I.SIMON_MIL', 'Thinks Jesus gave her medicine.', '{"question":"How did Jesus heal her?","wrong_answer":"Gave her medicine","correct_answer":"He rebuked the fever and it left"}'::jsonb, 'Illness at home is treated with medicine.', 'Offer "Gave her medicine" beside "He rebuked the fever and it left" and ask the child to choose.', 'Read Luke 4:39.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_EA.HEALING_SIMON_S_MOTHER_I.SIMON_MIL.M_C1_SIM_SLEPT', 'CRES.G1.THE_EA.HEALING_SIMON_S_MOTHER_I.SIMON_MIL', 'Thinks she slept after being healed.', '{"question":"What did she do after she was healed?","wrong_answer":"Went back to sleep","correct_answer":"Got up and served them"}'::jsonb, 'Sick people rest after getting better.', 'Offer "Went back to sleep" beside "Got up and served them" and ask the child to choose.', 'Act out getting up and serving food.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_EA.HEALING_SIMON_S_MOTHER_I.SIMON_MIL.M_C1_SIM_MOTHER', 'CRES.G1.THE_EA.HEALING_SIMON_S_MOTHER_I.SIMON_MIL', 'Thinks she was Simon''s own mother.', '{"question":"Whose mother-in-law was she?","wrong_answer":"Jesus''","correct_answer":"Simon''s (Simon Peter''s)"}'::jsonb, 'Mother-in-law is a new word.', 'Offer "Jesus''" beside "Simon''s (Simon Peter''s)" and ask the child to choose.', 'Explain: the mother of Simon''s wife.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CHRIST.SHARING.SHARE_HOME.M_C1_SH_TOWEL', 'CRES.G1.CHRIST.SHARING.SHARE_HOME', 'Thinks towels are shared by the whole family.', '{"question":"Is a bathing towel shared?","wrong_answer":"Yes","correct_answer":"No, it is personal"}'::jsonb, 'Towels hang together.', 'Offer "Yes" beside "No, it is personal" and ask the child to choose.', 'Two baskets: shared and personal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CHRIST.SHARING.SHARE_HOME.M_C1_SH_GREEDY', 'CRES.G1.CHRIST.SHARING.SHARE_HOME', 'Thinks the biggest share should go to the one who grabs first.', '{"question":"Food is on the table. Who should get it first?","wrong_answer":"Whoever grabs first","correct_answer":"Everyone shares fairly"}'::jsonb, 'Grabbing works in play.', 'Offer "Whoever grabs first" beside "Everyone shares fairly" and ask the child to choose.', 'Role-play serving fairly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CHRIST.SHARING.SHARE_HOME.M_C1_SH_TV_MINE', 'CRES.G1.CHRIST.SHARING.SHARE_HOME', 'Thinks the television belongs only to the child who likes it.', '{"question":"Who uses the TV at home?","wrong_answer":"Only me","correct_answer":"The whole family"}'::jsonb, 'Children claim favourite things.', 'Offer "Only me" beside "The whole family" and ask the child to choose.', 'Take turns choosing in role-play.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CHRIST.SHARING.SHARE_HOME.M_C1_SH_WHY', 'CRES.G1.CHRIST.SHARING.SHARE_HOME', 'Does not know why families share.', '{"question":"Why do families share?","wrong_answer":"Because they must","correct_answer":"To show love and care"}'::jsonb, 'Sharing is a rule without reason.', 'Offer "Because they must" beside "To show love and care" and ask the child to choose.', 'Ask how it feels when someone shares with you.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CHRIST.SHARING.BOY_LOAVES.M_C1_BL_NUMBERS', 'CRES.G1.CHRIST.SHARING.BOY_LOAVES', 'Swaps the numbers: two loaves and five fish.', '{"question":"How many loaves did the boy have?","wrong_answer":"Two","correct_answer":"Five"}'::jsonb, 'The numbers are easily swapped.', 'Offer "Two" beside "Five" and ask the child to choose.', 'Show five fingers for loaves, two for fish.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CHRIST.SHARING.BOY_LOAVES.M_C1_BL_KEPT', 'CRES.G1.CHRIST.SHARING.BOY_LOAVES', 'Thinks the boy kept his food.', '{"question":"What did the boy do with his food?","wrong_answer":"Ate it himself","correct_answer":"Gave it to Jesus"}'::jsonb, 'Children keep their lunch.', 'Offer "Ate it himself" beside "Gave it to Jesus" and ask the child to choose.', 'Act out giving the basket.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CHRIST.SHARING.BOY_LOAVES.M_C1_BL_WASTE', 'CRES.G1.CHRIST.SHARING.BOY_LOAVES', 'Thinks the leftovers were thrown away.', '{"question":"What happened to the leftover food?","wrong_answer":"Thrown away","correct_answer":"Gathered into twelve baskets"}'::jsonb, 'Leftovers are thrown away at home.', 'Offer "Thrown away" beside "Gathered into twelve baskets" and ask the child to choose.', 'Read John 6:12-13.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CHRIST.SHARING.BOY_LOAVES.M_C1_BL_FEW', 'CRES.G1.CHRIST.SHARING.BOY_LOAVES', 'Thinks only a few people ate.', '{"question":"How many people ate?","wrong_answer":"A few","correct_answer":"A very large crowd (about five thousand men)"}'::jsonb, 'Five loaves seems enough for a few.', 'Offer "A few" beside "A very large crowd (about five thousand men)" and ask the child to choose.', 'Show a crowd picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CHRIST.OBEDIENCE.OBEY_PARENTS.M_C1_OP_FEAR', 'CRES.G1.CHRIST.OBEDIENCE.OBEY_PARENTS', 'Thinks we obey parents only so we are not beaten.', '{"question":"Why should children obey parents?","wrong_answer":"So we are not beaten","correct_answer":"God says it is right, and it keeps us safe"}'::jsonb, 'Fear is the reason children hear.', 'Offer "So we are not beaten" beside "God says it is right, and it keeps us safe" and ask the child to choose.', 'Read Ephesians 6:1-3 simply.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CHRIST.OBEDIENCE.OBEY_PARENTS.M_C1_OP_LATER', 'CRES.G1.CHRIST.OBEDIENCE.OBEY_PARENTS', 'Thinks obeying later is the same as obeying.', '{"question":"Mother says \"come and eat\". When should you come?","wrong_answer":"After my game","correct_answer":"Straight away"}'::jsonb, 'Delay feels like obeying.', 'Offer "After my game" beside "Straight away" and ask the child to choose.', 'Play a game: obey at once when called.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CHRIST.OBEDIENCE.OBEY_PARENTS.M_C1_OP_MOTHER_ONLY', 'CRES.G1.CHRIST.OBEDIENCE.OBEY_PARENTS', 'Thinks only the mother must be obeyed.', '{"question":"Should you obey your father too?","wrong_answer":"No","correct_answer":"Yes, both parents (and guardians)"}'::jsonb, 'The child spends most time with mother.', 'Offer "No" beside "Yes, both parents (and guardians)" and ask the child to choose.', 'Read "honour your father and mother".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CHRIST.OBEDIENCE.OBEY_PARENTS.M_C1_OP_ANY_ADULT', 'CRES.G1.CHRIST.OBEDIENCE.OBEY_PARENTS', 'Thinks a child must obey any adult, even one asking to keep a secret or go somewhere alone.', '{"question":"A grown-up you do not know tells you to come with him. Should you obey?","wrong_answer":"Yes, obey adults","correct_answer":"No, say no and tell a trusted adult"}'::jsonb, 'Obedience is taught without limits.', 'Offer "Yes, obey adults" beside "No, say no and tell a trusted adult" and ask the child to choose.', 'Say: we obey parents and teachers. If anyone asks for something unsafe or secret, say no and tell.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CHRIST.HONESTY.TRUTH_G1.M_C1_TR_FUN_LIE', 'CRES.G1.CHRIST.HONESTY.TRUTH_G1', 'Thinks a lie told for fun is not a lie.', '{"question":"Is it a lie to say \"the teacher is coming\" when she is not, for fun?","wrong_answer":"No, it is fun","correct_answer":"Yes, it is a lie"}'::jsonb, 'Jokes and lies are confused.', 'Offer "No, it is fun" beside "Yes, it is a lie" and ask the child to choose.', 'Tell the story of the boy who cried wolf.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CHRIST.HONESTY.TRUTH_G1.M_C1_TR_PICK', 'CRES.G1.CHRIST.HONESTY.TRUTH_G1', 'Thinks picking up a friend''s eraser and keeping it is fine.', '{"question":"You find your friend''s eraser. What do you do?","wrong_answer":"Keep it","correct_answer":"Give it back"}'::jsonb, 'Found things seem free.', 'Offer "Keep it" beside "Give it back" and ask the child to choose.', 'Role-play returning it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CHRIST.HONESTY.TRUTH_G1.M_C1_TR_BLAME', 'CRES.G1.CHRIST.HONESTY.TRUTH_G1', 'Blames a sibling to avoid trouble.', '{"question":"You spilled the milk. What should you say?","wrong_answer":"My sister did it","correct_answer":"I spilled it, I am sorry"}'::jsonb, 'Blaming avoids punishment.', 'Offer "My sister did it" beside "I spilled it, I am sorry" and ask the child to choose.', 'Praise owning up with a sticker.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CHRIST.HONESTY.TRUTH_G1.M_C1_TR_GOD_SEE', 'CRES.G1.CHRIST.HONESTY.TRUTH_G1', 'Thinks a lie nobody hears is fine.', '{"question":"Does God know when we lie?","wrong_answer":"No","correct_answer":"Yes"}'::jsonb, 'Children think only adults can catch them.', 'Offer "No" beside "Yes" and ask the child to choose.', 'Talk about God knowing everything.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CHRIST.THANKFULNESS.THANK_PARENTS.M_C1_TP_GIFT_ONLY', 'CRES.G1.CHRIST.THANKFULNESS.THANK_PARENTS', 'Thinks only buying a present thanks parents.', '{"question":"How can a child thank parents without money?","wrong_answer":"He cannot","correct_answer":"Say thank you (help, obey, pray for them)"}'::jsonb, 'Thanks is linked with presents.', 'Offer "He cannot" beside "Say thank you (help, obey, pray for them)" and ask the child to choose.', 'List free ways to thank.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CHRIST.THANKFULNESS.THANK_PARENTS.M_C1_TP_DUTY', 'CRES.G1.CHRIST.THANKFULNESS.THANK_PARENTS', 'Thinks parents need not be thanked for food because it is their job.', '{"question":"Should you thank your mother for food?","wrong_answer":"No, it is her job","correct_answer":"Yes"}'::jsonb, 'Duties seem not to need thanks.', 'Offer "No, it is her job" beside "Yes" and ask the child to choose.', 'Ask how mother feels when thanked.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CHRIST.THANKFULNESS.THANK_PARENTS.M_C1_TP_ONCE', 'CRES.G1.CHRIST.THANKFULNESS.THANK_PARENTS', 'Thinks saying thank you once a year is enough.', '{"question":"How often should you thank your parents?","wrong_answer":"Once a year","correct_answer":"Every day"}'::jsonb, 'Thanks is linked with birthdays.', 'Offer "Once a year" beside "Every day" and ask the child to choose.', 'Make a daily thank-you habit chart.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.CHRIST.THANKFULNESS.THANK_PARENTS.M_C1_TP_GUARDIAN', 'CRES.G1.CHRIST.THANKFULNESS.THANK_PARENTS', 'Thinks only parents, not grandparents or guardians, should be thanked.', '{"question":"Should you thank your grandmother who cares for you?","wrong_answer":"No, only parents","correct_answer":"Yes"}'::jsonb, 'The outcome word "parents" is taken narrowly.', 'Offer "No, only parents" beside "Yes" and ask the child to choose.', 'Name all who care for us.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_CH.A_HOUSE_OF_GOD.CHURCH_G1.M_C1_CH_PLAYGROUND', 'CRES.G1.THE_CH.A_HOUSE_OF_GOD.CHURCH_G1', 'Thinks church is a place to run and play.', '{"question":"Can you run around in church during the service?","wrong_answer":"Yes","correct_answer":"No, sit quietly and listen"}'::jsonb, 'Church is a big open space.', 'Offer "Yes" beside "No, sit quietly and listen" and ask the child to choose.', 'Practise walking quietly into a pretend church.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_CH.A_HOUSE_OF_GOD.CHURCH_G1.M_C1_CH_BUILDING_ONLY', 'CRES.G1.THE_CH.A_HOUSE_OF_GOD.CHURCH_G1', 'Thinks church is only a big stone building.', '{"question":"Can Christians worship in a small church under a tree?","wrong_answer":"No","correct_answer":"Yes"}'::jsonb, 'Churches in pictures are big buildings.', 'Offer "No" beside "Yes" and ask the child to choose.', 'Show many kinds of churches.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_CH.A_HOUSE_OF_GOD.CHURCH_G1.M_C1_CH_SHOP', 'CRES.G1.THE_CH.A_HOUSE_OF_GOD.CHURCH_G1', 'Thinks church is a place to buy things.', '{"question":"What do people do in church?","wrong_answer":"Buy things","correct_answer":"Pray, sing and read the Bible"}'::jsonb, 'Collections and sales are seen at church.', 'Offer "Buy things" beside "Pray, sing and read the Bible" and ask the child to choose.', 'List worship activities with pictures.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_CH.A_HOUSE_OF_GOD.CHURCH_G1.M_C1_CH_DIRTY', 'CRES.G1.THE_CH.A_HOUSE_OF_GOD.CHURCH_G1', 'Thinks dropping papers in church does not matter.', '{"question":"Should you drop sweet papers in church?","wrong_answer":"Yes, someone will clean","correct_answer":"No, keep God''s house clean"}'::jsonb, 'Cleaning is someone else''s job.', 'Offer "Yes, someone will clean" beside "No, keep God''s house clean" and ask the child to choose.', 'Practise picking litter after a class service.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_CH.A_HOUSE_OF_PRAYER.PRAYER_TIMES.M_C1_PT_CHURCH_ONLY', 'CRES.G1.THE_CH.A_HOUSE_OF_PRAYER.PRAYER_TIMES', 'Thinks prayer can be said only in church.', '{"question":"Can you pray at home?","wrong_answer":"No, only in church","correct_answer":"Yes, anywhere"}'::jsonb, 'Prayer is seen in church.', 'Offer "No, only in church" beside "Yes, anywhere" and ask the child to choose.', 'Pray in class and talk about praying at home.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_CH.A_HOUSE_OF_PRAYER.PRAYER_TIMES.M_C1_PT_LONG', 'CRES.G1.THE_CH.A_HOUSE_OF_PRAYER.PRAYER_TIMES', 'Thinks a prayer must be long and use big words.', '{"question":"Is \"Thank you God for this food\" a prayer?","wrong_answer":"No, it is too short","correct_answer":"Yes"}'::jsonb, 'Adult prayers are long.', 'Offer "No, it is too short" beside "Yes" and ask the child to choose.', 'Say short prayers together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_CH.A_HOUSE_OF_PRAYER.PRAYER_TIMES.M_C1_PT_ASK_ONLY', 'CRES.G1.THE_CH.A_HOUSE_OF_PRAYER.PRAYER_TIMES', 'Thinks prayer is only asking for things.', '{"question":"Name something we can say to God apart from asking.","wrong_answer":"Nothing","correct_answer":"Thank you (sorry)"}'::jsonb, 'Children hear requests in prayer.', 'Offer "Nothing" beside "Thank you (sorry)" and ask the child to choose.', 'Sort prayer cards: thank you, please, sorry.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G1.THE_CH.A_HOUSE_OF_PRAYER.PRAYER_TIMES.M_C1_PT_SICK_ONLY', 'CRES.G1.THE_CH.A_HOUSE_OF_PRAYER.PRAYER_TIMES', 'Thinks we pray only when sick or in trouble.', '{"question":"When should we pray?","wrong_answer":"Only when sick","correct_answer":"Every day, morning and night, before meals"}'::jsonb, 'Prayer is linked with crises.', 'Offer "Only when sick" beside "Every day, morning and night, before meals" and ask the child to choose.', 'Make a day chart with prayer times.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
